def normshape(points):
    mr=min(r for r,c in points); mc=min(c for r,c in points)
    return frozenset((r-mr,c-mc) for r,c in points)
def transforms(ps):
    result=[]
    for k in range(4):
        q=[]
        for r,c in ps:
            # rotate 90 k on coordinate
            x,y=r,c
            for _ in range(k): x,y=y,-x
            q.append((x,y))
        for flip in [False,True]:
            qq=[(r,-c if flip else c) for r,c in q]
            result.append(normshape(qq))
    return set(result)
